# ---- Core extraction, matching & Excel-writing logic ----

import os
import re
import sys
from difflib import SequenceMatcher

import pdfplumber
import openpyxl
from openpyxl.styles import Font, Alignment, PatternFill, Border, Side
from openpyxl.utils import get_column_letter


# --------------------------------------------------------------------------
# 1. SHARED LOW-LEVEL HELPERS
# --------------------------------------------------------------------------

def clean(s):
    if s is None:
        return ""
    return re.sub(r"\s+", " ", str(s)).strip()


def to_float(s):
    if s is None:
        return None
    s = str(s).replace(",", "").replace("₹", "").strip()
    try:
        return float(s)
    except ValueError:
        return None


def gst_rate_to_pct(gst_rate_str):
    if not gst_rate_str:
        return None
    parts = re.findall(r"[\d.]+", str(gst_rate_str))
    return sum(float(p) for p in parts) if parts else None


# --------------------------------------------------------------------------
# 2. SAMPLE PRODUCT MASTER LIST + HSN GST-RATE MAP (SANITIZED)
# --------------------------------------------------------------------------
# Columns: (Category, Flavour, Grammage, Pieces Per Box, MRP per piece)
BUILT_IN_PRODUCT_MASTER = [
    ('Snacks', 'Sample Flavour A', 30, 120, 10),
    ('Snacks', 'Sample Flavour A', 50, 72, 20),
    ('Snacks', 'Sample Flavour B', 40, 144, 20),
    ('Beverages', 'Sample Drink A', 250, 24, 40),
    ('Confectionery', 'Sample Sweet A', 500, 18, 150),
]

HSN_GST_RATE_MAP = {
    "19053100": "5%",
    "20052000": "5%",
    "21069099": "5%",
    "22021010": "40%",
    "998361": "18%",
}


# --------------------------------------------------------------------------
# 3. SHARED PRODUCT MATCHING
# --------------------------------------------------------------------------

MATCH_CONFIDENCE_THRESHOLD = 0.50

GLUED_WORD_FIXES = {
    re.compile(r"sampleitem", re.IGNORECASE): "sample item",
}

PURCHASE_NAME_ALIASES = {
    "Product Alias A": "Canonical Name A",
}


def normalize_purchase_description(desc):
    d = (desc or "").replace("\n", " ")
    d = re.sub(r"^\s*[A-Za-z]_", "", d)
    d = re.sub(r"(?<=[a-z])(?=[A-Z])", " ", d)
    for glued, spaced in GLUED_WORD_FIXES.items():
        d = glued.sub(spaced, d)
    d = d.replace("_", " ")
    d = re.sub(r"\s+\d+\.\d+\s*$", "", d)
    d = re.sub(r"\s+", " ", d).strip()
    for alias, canonical in PURCHASE_NAME_ALIASES.items():
        if alias.lower() in d.lower():
            d = re.sub(re.escape(alias), canonical, d, flags=re.IGNORECASE)
    return d


def normalize_product_text(s):
    s = (s or "").upper()
    s = re.sub(r"\bP/P\b|\bPET\b|\bCAN\b|\bN\b", " ", s)
    s = re.sub(r"\(.*?\)", " ", s)
    s = re.sub(r"\d+\s*(?:PCS|PKT|GMS|GM|G|ML|BOX)\b", " ", s, flags=re.IGNORECASE)
    s = re.sub(r"\bRS\s*\d+.*", " ", s, flags=re.IGNORECASE)
    s = re.sub(r"NO\.?\s*(\d+)", r"NO \1", s)
    s = re.sub(r"[^A-Z0-9\s]", " ", s)
    s = re.sub(r"\s+", " ", s).strip()
    return s


def extract_grammage_for_matching(desc):
    m = re.search(r"(\d+)\s*(?:gms|gm|g)\b", desc or "", re.IGNORECASE)
    if m:
        return int(m.group(1))
    m = re.search(r"(\d+)\s*\(", desc or "")
    return int(m.group(1)) if m else None


def build_product_master(rows):
    master = []
    for row in rows:
        if not row or len(row) < 2:
            continue
        category, flavour = row[0], row[1]
        grammage = row[2] if len(row) > 2 else None
        pieces_per_box = row[3] if len(row) > 3 else None
        mrp = row[4] if len(row) > 4 else None
        if not category or not flavour:
            continue
        master.append({
            "category": clean(category),
            "flavour": clean(flavour),
            "grammage": grammage,
            "pieces_per_box": pieces_per_box,
            "mrp": mrp,
            "search_text": normalize_product_text(f"{category} {flavour}"),
        })
    return master


def load_product_master(path):
    wb = openpyxl.load_workbook(path, data_only=True)
    ws = wb.active
    rows_iter = ws.iter_rows(min_row=1, values_only=True)
    header_row = next(rows_iter, None)
    header = [clean(h).upper() if h else "" for h in (header_row or [])]

    def find_idx(*keywords):
        for i, h in enumerate(header):
            if any(k in h for k in keywords):
                return i
        return None

    idx_cat = find_idx("CATEGORY") or 0
    idx_flavour = find_idx("FLAVOUR", "FLAVOR")
    idx_gram = find_idx("GRAM")
    idx_pieces = find_idx("PIECE", "PCS", "BOX")
    idx_mrp = find_idx("MRP")
    if idx_flavour is None:
        idx_flavour = 1
    if idx_gram is None:
        idx_gram = 2
    if idx_mrp is None:
        idx_mrp = 4 if idx_pieces is not None else 3

    def get(row, idx):
        return row[idx] if (idx is not None and idx < len(row)) else None

    rows = []
    for row in rows_iter:
        if not row:
            continue
        rows.append((get(row, idx_cat), get(row, idx_flavour), get(row, idx_gram),
                     get(row, idx_pieces), get(row, idx_mrp)))
    return build_product_master(rows)


def get_default_product_master():
    return build_product_master(BUILT_IN_PRODUCT_MASTER)


def match_product(raw_description, master, is_purchase_format=False):
    if not master:
        return None, 0.0
    pre = normalize_purchase_description(raw_description) if is_purchase_format else (raw_description or "")
    grammage = extract_grammage_for_matching(pre)
    query_text = normalize_product_text(pre)
    query = " ".join(sorted(query_text.split()))
    best, best_score = None, 0.0
    for row in master:
        candidate = " ".join(sorted(row["search_text"].split()))
        score = SequenceMatcher(None, query, candidate).ratio()
        if grammage is not None and row["grammage"] is not None:
            try:
                if abs(int(row["grammage"]) - int(grammage)) <= 1:
                    score += 0.03
            except (ValueError, TypeError):
                pass
        if score > best_score:
            best_score, best = score, row
    return best, min(best_score, 1.0)


# --------------------------------------------------------------------------
# 4. SALE-INVOICE EXTRACTION (Standard ERP / Tally Layout)
# --------------------------------------------------------------------------

def find_label_cell(rows, label, exact=False):
    for row in rows:
        for cell in row:
            if not cell:
                continue
            lines = [l.strip() for l in str(cell).split("\n") if l.strip()]
            if not lines:
                continue
            first = lines[0]
            if (first == label) if exact else first.startswith(label):
                return lines
    return None


HEADER_BLOCK_LABELS = ["Consignee (Ship to)", "Buyer (Bill to)"]


def segment_cell_by_labels(cell_text):
    lines = [l.strip() for l in str(cell_text).split("\n") if l.strip()]
    segments = {"pre": []}
    current_key = "pre"
    for l in lines:
        if l in HEADER_BLOCK_LABELS:
            current_key = l
            segments[current_key] = []
        else:
            segments[current_key].append(l)
    return segments


def parse_invoice_header_blocks(rows):
    seller_lines, ship_lines, bill_lines = None, None, None
    for row in rows:
        for cell in row:
            if not cell:
                continue
            segs = segment_cell_by_labels(cell)
            if seller_lines is None and segs["pre"] and "GSTIN/UIN" in " ".join(segs["pre"]):
                seller_lines = segs["pre"]
            if ship_lines is None and "Consignee (Ship to)" in segs:
                ship_lines = segs["Consignee (Ship to)"]
            if bill_lines is None and "Buyer (Bill to)" in segs:
                bill_lines = segs["Buyer (Bill to)"]
    return seller_lines, ship_lines, bill_lines


def build_party_dict(lines):
    if not lines:
        return {"name": "", "address": "", "gstin": "", "state": "", "city": ""}
    name = lines[0]
    gstin, gstin_idx = "", None
    state, state_idx = "", None
    for i, l in enumerate(lines[1:], start=1):
        gm = re.search(r"GSTIN/UIN\s*:?\s*([0-9A-Z]{15})", l)
        if gm and gstin_idx is None:
            gstin, gstin_idx = gm.group(1), i
        sm = re.match(r"State Name\s*:?\s*([A-Za-z ]+?)\s*,\s*Code", l, re.IGNORECASE)
        if sm and state_idx is None:
            state, state_idx = sm.group(1).strip(), i

    addr_lines = lines[1:gstin_idx] if gstin_idx is not None else lines[1:]
    addr_lines = [l for l in addr_lines if not l.upper().startswith("STATE NAME")]

    city = ""
    tail = [t.strip() for t in ", ".join(addr_lines).split(",") if t.strip()]
    tail = [t for t in tail if not re.fullmatch(r"\d{5,6}", t)]
    if tail:
        for t in reversed(tail):
            if state and t.lower() == state.lower():
                continue
            city = t
            break

    return {"name": name, "address": ", ".join(addr_lines), "gstin": gstin, "state": state, "city": city}


def sale_extract_header_fields(full_text, main_table_rows):
    fields = {}
    lines = find_label_cell(main_table_rows, "Invoice No.")
    fields["invoice_no"] = lines[1] if lines and len(lines) > 1 else ""

    lines = find_label_cell(main_table_rows, "Dated", exact=True)
    fields["date"] = lines[1] if lines and len(lines) > 1 else ""
    if not fields["date"]:
        m = re.search(r"Invoice No\.\s*Dated\s*\n\S+\s+(\d{1,2}-[A-Za-z]{3}-\d{2,4})", full_text)
        fields["date"] = m.group(1) if m else ""

    lines = find_label_cell(main_table_rows, "Motor Vehicle No.")
    fields["vehicle_no"] = lines[1] if lines and len(lines) > 1 else ""

    lines = find_label_cell(main_table_rows, "Reference No. & Date.")
    fields["reference_no"] = clean(lines[1]) if lines and len(lines) > 1 else ""

    lines = find_label_cell(main_table_rows, "Mode/Terms of Payment")
    fields["payment_terms"] = lines[1] if lines and len(lines) > 1 else ""

    lines = find_label_cell(main_table_rows, "Dispatched through")
    fields["dispatched_through"] = lines[1] if lines and len(lines) > 1 else ""

    m = re.search(r"Ack No\.?\s*:?\s*(\S+)", full_text)
    fields["ack_no"] = m.group(1) if m else ""

    fields["gst_scheme"] = "IGST" if re.search(r"\bIGST\b", full_text) else (
        "CGST+SGST" if re.search(r"\bCGST\b", full_text) else "UNKNOWN"
    )

    m = re.search(r"₹\s*([\d,]+\.\d{2})", full_text)
    if not m:
        m = re.search(r"Total\s+[\d,.]+\s*Box\s*\S*\s*([\d,]+\.\d{2})\s*$", full_text, re.MULTILINE)
    fields["grand_total"] = to_float(m.group(1)) if m else None
    return fields


PCS_PER_BOX_RE_LIST = [
    re.compile(r"(\d+)\s*(?:pcs|pkt)", re.IGNORECASE),
    re.compile(r"(\d+)\s*RS\s*\d", re.IGNORECASE),
    re.compile(r"(\d+)\s*\(\s*\d+/-\s*\)"),
]

MRP_PER_PIECE_RE_LIST = [
    re.compile(r"(?:pcs|pkt)\s+(\d+)\s*/-", re.IGNORECASE),
    re.compile(r"\bRS\.?\s*(\d+)\s*/-", re.IGNORECASE),
    re.compile(r"\(\s*(\d+)\s*/-\s*\)"),
]


def mrp_per_piece_from_desc(desc):
    for pattern in MRP_PER_PIECE_RE_LIST:
        m = pattern.search(desc or "")
        if m:
            return to_float(m.group(1))
    return None


def pcs_per_box_from_desc(desc):
    if not desc:
        return None
    for pattern in PCS_PER_BOX_RE_LIST:
        m = pattern.search(desc)
        if m:
            return int(m.group(1))
    return None


def compute_derived_fields(item):
    pcs = pcs_per_box_from_desc(item.get("description"))
    rate = item.get("rate")
    amount = item.get("amount")

    if not item.get("gst_rate"):
        looked_up = HSN_GST_RATE_MAP.get(item.get("hsn_sac", ""))
        if looked_up:
            item["gst_rate"] = looked_up
            item["gst_rate_source"] = "HSN lookup (fallback)"
    elif not item.get("gst_rate_source"):
        item["gst_rate_source"] = "invoice"

    gst_pct = gst_rate_to_pct(item.get("gst_rate"))
    item["pcs_per_box"] = pcs
    item["rate_per_pcs"] = round(rate / pcs, 2) if (rate is not None and pcs) else None
    item["gst_amount"] = round(amount * gst_pct / 100, 2) if (amount is not None and gst_pct is not None) else None
    item["amount_incl_gst"] = (
        round(amount + item["gst_amount"], 2) if (amount is not None and item["gst_amount"] is not None) else None
    )
    return item


_HSN_RE = re.compile(r"\d{6,8}")
_QTY_UNIT_RE = re.compile(r"^[\d,]+\.\d{2,3}\s+[A-Za-z]+$")
_AMOUNT_RE = re.compile(r"^[\d,]+\.\d{2}$")
_PERCENT_RE = re.compile(r"^\d+(\.\d+)?\s*%$")


def find_header_column_indices(rows):
    for row in rows:
        idx_gst, idx_disc = None, None
        for i, cell in enumerate(row):
            if not cell:
                continue
            first_line = str(cell).strip().split("\n")[0].strip().upper()
            if idx_gst is None and first_line.startswith("GST"):
                idx_gst = i
            if idx_disc is None and first_line.startswith("DISC"):
                idx_disc = i
        if idx_gst is not None or idx_disc is not None:
            return idx_gst, idx_disc
    return None, None


def sale_extract_items_from_rows(rows):
    items = []
    seen = set()
    gst_col_idx, disc_col_idx = find_header_column_indices(rows)

    for row in rows:
        cells = [clean(c) for c in row]
        if not any(cells):
            continue

        sl = cells[0]
        if not re.fullmatch(r"\d{1,3}", sl):
            continue

        hsn = next((c for c in cells if _HSN_RE.fullmatch(c)), "")
        qty_unit = next((c for c in cells if _QTY_UNIT_RE.fullmatch(c)), "")

        gst_rate_cell = ""
        if gst_col_idx is not None:
            if gst_col_idx < len(cells) and _PERCENT_RE.fullmatch(cells[gst_col_idx]):
                gst_rate_cell = cells[gst_col_idx]
        else:
            qty_idx = next((i for i, c in enumerate(cells) if c == qty_unit and qty_unit), None)
            for i, c in enumerate(cells):
                if i == disc_col_idx:
                    continue
                if _PERCENT_RE.fullmatch(c) and (qty_idx is None or i < qty_idx):
                    gst_rate_cell = c
                    break

        qty, unit = None, ""
        if qty_unit:
            parts = qty_unit.split()
            qty = to_float(parts[0])
            unit = parts[1]

        discount_pct = None
        if disc_col_idx is not None and disc_col_idx < len(cells):
            dc = cells[disc_col_idx]
            if _PERCENT_RE.fullmatch(dc):
                discount_pct = gst_rate_to_pct(dc)

        desc = ""
        for c in cells[1:]:
            if not c or c == hsn or c == qty_unit or c == gst_rate_cell:
                continue
            if _AMOUNT_RE.fullmatch(c) or c.lower() in ("box", "pcs", "kg", "ltr", "nos"):
                continue
            desc = c
            break

        numeric_only = [c for c in cells if _AMOUNT_RE.fullmatch(c)]
        amount = to_float(numeric_only[-1]) if numeric_only else None
        rate = to_float(numeric_only[0]) if len(numeric_only) >= 2 else None

        key = (sl, desc, amount, qty)
        if key in seen:
            continue
        seen.add(key)

        items.append({
            "sl_no": sl,
            "description": desc,
            "hsn_sac": hsn,
            "gst_rate": gst_rate_cell,
            "gst_rate_source": "invoice" if gst_rate_cell else "",
            "quantity": qty,
            "unit": unit,
            "rate": rate,
            "amount": amount,
            "discount_pct": discount_pct,
        })
    return items


def extract_hsn_breakdown_map(rows):
    result = {}
    for row in rows:
        raw_cells = ["" if c is None else str(c) for c in row]
        first_raw = raw_cells[0].strip()
        if not first_raw:
            continue
        hsn_lines = [l.strip() for l in first_raw.split("\n") if l.strip()]
        if not hsn_lines or not all(_HSN_RE.fullmatch(h) for h in hsn_lines):
            continue
        n = len(hsn_lines)

        def split_col(raw):
            return [p.strip() for p in raw.split("\n") if p.strip()]

        percent_cols, amount_cols = [], []
        for raw in raw_cells[1:]:
            raw = raw.strip()
            if not raw:
                continue
            parts = split_col(raw)
            if len(parts) != n:
                continue
            if all(_PERCENT_RE.fullmatch(p) for p in parts):
                percent_cols.append(parts)
            elif all(_AMOUNT_RE.fullmatch(p) for p in parts):
                amount_cols.append(parts)

        for idx, hsn in enumerate(hsn_lines):
            percents = [float(re.sub("%", "", col[idx])) for col in percent_cols]
            amounts = [to_float(col[idx]) for col in amount_cols]
            if not percents:
                continue
            result[hsn] = {
                "total_pct": sum(percents),
                "taxable": amounts[0] if amounts else None,
                "tax_amount": amounts[-1] if len(amounts) > 1 else None,
            }
    return result


def sale_split_pages_into_invoice_groups(pages):
    groups, current = [], []
    for page in pages:
        text = page.extract_text() or ""
        first_line = text.strip().split("\n")[0] if text.strip() else ""
        is_continuation = "(Page" in first_line
        if not is_continuation and current:
            groups.append(current)
            current = []
        current.append(page)
    if current:
        groups.append(current)
    return groups


def sale_parse_invoice_group(pages, source_file):
    full_text = "\n".join(p.extract_text() or "" for p in pages)
    combined_rows = []
    for p in pages:
        for t in p.extract_tables():
            combined_rows.extend(t)

    header = sale_extract_header_fields(full_text, combined_rows)
    seller_lines, ship_lines, bill_lines = parse_invoice_header_blocks(combined_rows)
    seller = build_party_dict(seller_lines)
    ship_to = build_party_dict(ship_lines)
    bill_to = build_party_dict(bill_lines)
    items = sale_extract_items_from_rows(combined_rows)

    hsn_map = extract_hsn_breakdown_map(combined_rows)
    for item in items:
        if not item.get("gst_rate"):
            info = hsn_map.get(item.get("hsn_sac", ""))
            if info and info.get("total_pct") is not None:
                item["gst_rate"] = f"{info['total_pct']:g}%"
                item["gst_rate_source"] = "HSN breakdown table"
        compute_derived_fields(item)

    item_amounts = [it["amount"] for it in items if it.get("amount") is not None]
    item_gst_amounts = [it["gst_amount"] for it in items if it.get("gst_amount") is not None]
    header["taxable_value"] = round(sum(item_amounts), 2) if item_amounts else None
    header["tax_amount"] = round(sum(item_gst_amounts), 2) if item_gst_amounts else None

    return {
        "file": source_file,
        "header": header,
        "seller": seller,
        "bill_to": bill_to,
        "ship_to": ship_to,
        "items": items,
    }


def sale_parse_invoices_from_pdf(pdf_path):
    invoices = []
    with pdfplumber.open(pdf_path) as pdf:
        for grp in sale_split_pages_into_invoice_groups(pdf.pages):
            invoices.append(sale_parse_invoice_group(grp, os.path.basename(pdf_path)))
    return invoices


def sale_apply_product_matching(invoices, master):
    for inv in invoices:
        for item in inv["items"]:
            row, score = match_product(item.get("description", ""), master, is_purchase_format=False)
            if row and score >= MATCH_CONFIDENCE_THRESHOLD:
                grammage_str = f" {row['grammage']}g" if row["grammage"] else ""
                item["matched_product"] = f"{row['category']} - {row['flavour']}{grammage_str}"
                item["matched_category"] = row["category"]
                item["matched_flavour"] = row["flavour"]
                item["matched_grammage"] = row["grammage"]
                item["matched_mrp"] = row.get("mrp")
                if row.get("pieces_per_box"):
                    try:
                        item["pcs_per_box"] = int(row["pieces_per_box"])
                        item["rate_per_pcs"] = round(item["rate"] / item["pcs_per_box"], 2) if item.get("rate") is not None else None
                    except (ValueError, TypeError):
                        pass
            else:
                item["matched_product"] = "No Match"
            item["match_confidence"] = round(score, 2)


SALE_REGISTER_COLUMNS = [
    "PO NUMBER", "ODERING DATE", "PURCHASE DATE", "PURCHASE INVOICE",
    "SALE INVOICE", "SALE DATE", "PARTY NAME", "BRAND", "PRODUCTS CATEGORY",
    "PRODUCT NAME", "FLAVOUR", "PLANT OF PRODUCTION", "GRAMMAGE",
    "PIECES PER BOX", "BOX ORDERED", "EXPIRY DATE", "MANUFACTURING DATE",
    "TOTAL PIECES PURCHASED", "MASTER CART PACKAGING", "MOTOR VEHICLE NO.",
    "STATION OF SALE", "CITY OF SALE", "STATE OF SALE", "SALES EXECUTIVE",
    "MRP/PIECE", "PUR RATE W/O GST", "DISCOUNT ON PUR RATE",
    "EFFECTIVE PUR RATE W/O GST", "BOXES SOLD", "TOTAL PIECES SOLD",
    "SALE RATE W/O GST", "DISCOUNT ON SALE PRICE", "EFFECTIVE SALE RATE W/O GST",
    "GST ", "PURC RATE WITH GST", "SALE RATE WITH GST", "TOTAL COST PRICE",
    "TOTAL SALE PRICE", "TOTAL SALE PRICE EXCLUSIVE OF GST",
    "TOTAL COST PRICE EXCLUSIVE OF GST", "MODE OF PAYMENT",
    "PUR. EWAY BILL NO.", "ACK NO.", "TRANSPORT DISTANCE", "TRANSPORTER NAME",
]


def blank_sale_register_row():
    return {col: "" for col in SALE_REGISTER_COLUMNS}


def parse_sale_reference_no(reference_no):
    if not reference_no:
        return "", ""
    m = re.match(r"^(\S+)\s+dt\.?\s*(.+)$", reference_no.strip(), re.IGNORECASE)
    if m:
        return m.group(1).strip(), m.group(2).strip()
    return reference_no.strip(), ""


def build_sale_register_rows(invoices):
    rows = []
    for inv in invoices:
        h = inv["header"]
        bt = inv["bill_to"]
        st = inv["ship_to"]
        pur_inv_no, pur_date = parse_sale_reference_no(h.get("reference_no", ""))

        for item in inv["items"]:
            row = blank_sale_register_row()
            desc = item.get("description", "")
            row["PURCHASE INVOICE"] = pur_inv_no
            row["PURCHASE DATE"] = pur_date
            row["SALE INVOICE"] = h.get("invoice_no", "")
            row["SALE DATE"] = h.get("date", "")
            row["PARTY NAME"] = st.get("name", "") or bt.get("name", "")
            row["BRAND"] = "Primary Brand"
            row["PRODUCTS CATEGORY"] = item.get("matched_category", "")
            row["PRODUCT NAME"] = desc
            row["FLAVOUR"] = item.get("matched_flavour", "")
            row["GRAMMAGE"] = item.get("matched_grammage") or extract_grammage_for_matching(desc)
            row["PIECES PER BOX"] = item.get("pcs_per_box")
            row["MRP/PIECE"] = item.get("matched_mrp") or mrp_per_piece_from_desc(desc)
            row["MASTER CART PACKAGING"] = item.get("unit", "")
            row["MOTOR VEHICLE NO."] = h.get("vehicle_no", "")
            row["CITY OF SALE"] = st.get("city", "") or bt.get("city", "")
            row["STATE OF SALE"] = st.get("state", "") or bt.get("state", "")
            row["BOXES SOLD"] = item.get("quantity")
            pcs = item.get("pcs_per_box")
            qty = item.get("quantity")
            row["TOTAL PIECES SOLD"] = round(qty * pcs) if (qty is not None and pcs) else None
            rate = item.get("rate")
            amount = item.get("amount")
            row["SALE RATE W/O GST"] = rate
            row["DISCOUNT ON SALE PRICE"] = item.get("discount_pct")
            row["EFFECTIVE SALE RATE W/O GST"] = round(amount / qty, 2) if (amount is not None and qty) else rate
            gst_pct = gst_rate_to_pct(item.get("gst_rate"))
            row["GST "] = item.get("gst_rate", "")
            eff_rate = row["EFFECTIVE SALE RATE W/O GST"]
            row["SALE RATE WITH GST"] = round(eff_rate * (1 + gst_pct / 100), 2) if (eff_rate is not None and gst_pct is not None) else None
            row["TOTAL SALE PRICE"] = item.get("amount_incl_gst")
            row["TOTAL SALE PRICE EXCLUSIVE OF GST"] = amount
            row["MODE OF PAYMENT"] = h.get("payment_terms", "")
            row["ACK NO."] = h.get("ack_no", "")
            row["TRANSPORTER NAME"] = h.get("dispatched_through", "")
            rows.append(row)
    return rows


