def purchase_extract_header_fields(full_text):
    fields = {}
    m = re.search(r"PAN\s*:\s*\S+\s*\n(.+?)\n\s*CIN\s*:", full_text)
    fields["seller_name"] = clean(m.group(1)) if m else ""
    m = re.search(r"Ship To:\s*(.+?)(?:\s{2,}\S|\s+Payment Terms|\n)", full_text)
    fields["ship_to_name"] = clean(m.group(1)) if m else ""
    m = re.search(r"([A-Za-z]+),\s*[A-Za-z]+,\s*India\s+\d{6}", full_text)
    fields["plant_of_production"] = m.group(1) if m else ""
    m = re.search(r"Invoice No\.?:\s*(\S+)", full_text)
    fields["invoice_no"] = m.group(1) if m else ""
    m = re.search(r"Invoice Date:\s*([\d.]+)", full_text)
    fields["invoice_date"] = m.group(1) if m else ""
    m = re.search(r"SAP Ref\.?\s*No:\s*(\S+)", full_text)
    fields["sap_ref_no"] = m.group(1) if m else ""
    m = re.search(r"Place Of Supply:\s*(\S+)", full_text)
    fields["place_of_supply"] = m.group(1) if m else ""
    m = re.search(r"Vehicle No\.?:\s*(\S+)", full_text)
    fields["vehicle_no"] = m.group(1) if m else ""
    m = re.search(r"E-Way (?:Bill )?No\.?:?\s*(\d+)", full_text)
    fields["eway_no"] = m.group(1) if m else ""
    m = re.search(r"TPT:\s*(.+?)(?:\s{2,}\S|\s+Ship To|\n)", full_text)
    fields["transporter"] = clean(m.group(1)) if m else ""
    m = re.search(r"Ref No\.?:\s*([^\n]+)", full_text)
    fields["po_number"] = clean(m.group(1)) if m else ""
    m = re.search(r"SO No\.?:\s*(\S+)\s+([\d.]+)", full_text)
    fields["so_no"] = m.group(1) if m else ""
    fields["ordering_date"] = m.group(2) if m else ""
    m = re.search(r"Payment Terms:\s*([^\n]+)", full_text)
    fields["payment_terms"] = clean(m.group(1)) if m else ""
    m = re.search(r"Due Date:\s*([\d.\-]+)", full_text)
    fields["due_date"] = m.group(1) if m else ""
    m = re.search(r"Total Invoice Amount\s+([\d,]+\.\d{2})", full_text)
    fields["grand_total"] = to_float(m.group(1)) if m else None
    return fields


COLUMN_NAME_ALIASES = {
    "sn": ["SN."],
    "desc": ["PRODUCT DESCRIPTION"],
    "hsn": ["HSN/SAC"],
    "batch_exp": ["BATCH/ EXP DATE", "BATCH/EXP DATE"],
    "dispatch_qty": ["DISPATCH QTY"],
    "dispatch_uom": ["DISPATCH UOM"],
    "billing_qty": ["BILLING QTY (EA)", "BILLING QTY(EA)"],
    "mrp": ["MRP."],
    "unit_price": ["UNIT PRICE"],
    "adi_disc": ["ADI. DISC %"],
    "flat_disc": ["FLAT DISC AMOUNT"],
    "freight_disc": ["FREIGHT DISC %"],
    "amt_before_td": ["AMT. BEFORE TD"],
    "trade_disc": ["TRADE DISC %"],
    "taxable_value": ["TAXABLE VALUE"],
    "gst_pct": ["GST%"],
    "line_total": ["LINE TOTAL"],
}


def resolve_column_map(header_row):
    raw = {clean(cell).upper(): i for i, cell in enumerate(header_row) if cell}
    resolved = {}
    for field, aliases in COLUMN_NAME_ALIASES.items():
        for alias in aliases:
            if alias in raw:
                resolved[field] = raw[alias]
                break
    return resolved


def find_item_header_row(rows):
    for row in rows:
        cells = [clean(c).upper() if c else "" for c in row]
        if "SN." in cells and "PRODUCT DESCRIPTION" in cells:
            return row
    return None


def purchase_extract_items_from_rows(rows, pending=None):
    header_row = find_item_header_row(rows)
    if not header_row:
        return [], pending
    col = resolve_column_map(header_row)

    def val(row, field):
        idx = col.get(field)
        return clean(row[idx]) if (idx is not None and idx < len(row)) else ""

    items = []
    checked_for_continuation = False
    for row in rows:
        if row is header_row:
            continue
        cells = [clean(c) if c else "" for c in row]
        if not any(cells):
            continue

        sn = val(row, "sn")
        if not re.fullmatch(r"\d{1,3}", sn):
            if not checked_for_continuation and pending is not None:
                desc_frag = val(row, "desc")
                batch_frag = val(row, "batch_exp")
                if desc_frag:
                    pending["description"] = clean(f"{pending['description']} {desc_frag}")
                if batch_frag and not pending.get("expiry_date"):
                    m = re.search(r"(\d{1,2}\.\d{1,2}\.\d{2,4})", batch_frag)
                    if m:
                        pending["expiry_date"] = m.group(1)
            checked_for_continuation = True
            continue

        checked_for_continuation = True
        desc = val(row, "desc")
        hsn = val(row, "hsn")
        batch_exp = val(row, "batch_exp")
        batch, exp_date = "", ""
        if batch_exp:
            parts = batch_exp.split()
            if parts:
                batch = parts[0]
            m = re.search(r"(\d{1,2}\.\d{1,2}\.\d{2,4})", batch_exp)
            exp_date = m.group(1) if m else (parts[1] if len(parts) > 1 else "")

        dispatch_qty = to_float(val(row, "dispatch_qty"))
        dispatch_uom = val(row, "dispatch_uom")
        billing_qty = to_float(val(row, "billing_qty"))
        mrp = to_float(val(row, "mrp"))
        unit_price = to_float(val(row, "unit_price"))
        adi_disc = to_float(val(row, "adi_disc")) or 0.0
        trade_disc = to_float(val(row, "trade_disc")) or 0.0
        taxable_value = to_float(val(row, "taxable_value"))
        gst_pct = to_float(val(row, "gst_pct"))
        line_total = to_float(val(row, "line_total"))

        item = {
            "sl_no": sn,
            "description": desc,
            "hsn_sac": hsn,
            "batch": batch,
            "expiry_date": exp_date,
            "dispatch_qty": dispatch_qty,
            "dispatch_uom": dispatch_uom,
            "billing_qty": billing_qty,
            "pcs_per_box": round(billing_qty / dispatch_qty) if (billing_qty and dispatch_qty) else None,
            "mrp": mrp,
            "unit_price": unit_price,
            "discount_pct": round(adi_disc + trade_disc, 2),
            "taxable_value": taxable_value,
            "gst_rate": f"{gst_pct:g}%" if gst_pct is not None else "",
            "line_total": line_total,
        }
        items.append(item)
        pending = item
    return items, pending


def purchase_extract_items_from_pages(pages):
    all_items, pending = [], None
    for page in pages:
        for table in page.extract_tables():
            found, pending = purchase_extract_items_from_rows(table, pending=pending)
            all_items.extend(found)
    return all_items


def purchase_parse_invoice_group(pages, source_file):
    full_text = "\n".join(p.extract_text() or "" for p in pages)
    header = purchase_extract_header_fields(full_text)
    items = purchase_extract_items_from_pages(pages)
    for item in items:
        if not item.get("gst_rate"):
            fallback = HSN_GST_RATE_MAP.get(item.get("hsn_sac", ""))
            if fallback:
                item["gst_rate"] = fallback
    return {"file": source_file, "header": header, "items": items}


def purchase_split_pages_into_invoice_groups(pages):
    groups, current, current_invoice_no = [], [], None
    for page in pages:
        text = page.extract_text() or ""
        m = re.search(r"Invoice No\.?:\s*(\S+)", text)
        inv_no = m.group(1) if m else None
        if inv_no and current_invoice_no and inv_no != current_invoice_no and current:
            groups.append(current)
            current = []
        if inv_no:
            current_invoice_no = inv_no
        current.append(page)
    if current:
        groups.append(current)
    return groups


def purchase_parse_invoices_from_pdf(pdf_path):
    invoices = []
    with pdfplumber.open(pdf_path) as pdf:
        for grp in purchase_split_pages_into_invoice_groups(pdf.pages):
            invoices.append(purchase_parse_invoice_group(grp, os.path.basename(pdf_path)))
    return invoices


def purchase_apply_product_matching(invoices, master):
    for inv in invoices:
        for item in inv["items"]:
            row, score = match_product(item.get("description", ""), master, is_purchase_format=True)
            if row and score >= MATCH_CONFIDENCE_THRESHOLD:
                grammage_str = f" {row['grammage']}g" if row["grammage"] else ""
                item["matched_product"] = f"{row['category']} - {row['flavour']}{grammage_str}"
                item["matched_category"] = row["category"]
                item["matched_flavour"] = row["flavour"]
                item["matched_grammage"] = row["grammage"]
            else:
                item["matched_product"] = "No Match"
            item["match_confidence"] = round(score, 2)


def blank_purchase_register_row():
    return {col: "" for col in SALE_REGISTER_COLUMNS}


def aggregate_purchase_items_by_product(items):
    groups, order = {}, []
    for item in items:
        key = (item.get("hsn_sac", ""), clean(item.get("description", "")))
        if key not in groups:
            groups[key] = []
            order.append(key)
        groups[key].append(item)

    aggregated = []
    for key in order:
        group = groups[key]
        if len(group) == 1:
            aggregated.append(group[0])
            continue
        first = group[0]
        combined = dict(first)
        combined["batch"] = ", ".join(sorted({g.get("batch", "") for g in group if g.get("batch")}))
        combined["batch_count"] = len(group)
        combined["dispatch_qty"] = round(sum(g.get("dispatch_qty") or 0 for g in group), 3)
        combined["billing_qty"] = round(sum(g.get("billing_qty") or 0 for g in group), 3)
        combined["pcs_per_box"] = round(combined["billing_qty"] / combined["dispatch_qty"]) if combined["dispatch_qty"] else first.get("pcs_per_box")
        combined["taxable_value"] = round(sum(g.get("taxable_value") or 0 for g in group), 2)
        combined["line_total"] = round(sum(g.get("line_total") or 0 for g in group), 2)
        total_qty = combined["billing_qty"] or 0
        if total_qty:
            combined["unit_price"] = round(sum((g.get("unit_price") or 0) * (g.get("billing_qty") or 0) for g in group) / total_qty, 2)
            combined["discount_pct"] = round(sum((g.get("discount_pct") or 0) * (g.get("billing_qty") or 0) for g in group) / total_qty, 2)
        aggregated.append(combined)
    return aggregated


def build_purchase_register_rows(invoices):
