def detect_invoice_format(pdf_path):
    try:
        with pdfplumber.open(pdf_path) as pdf:
            text = (pdf.pages[0].extract_text() or "") if pdf.pages else ""
    except Exception:
        text = ""
    if "DISPATCH QTY" in text.upper() or "BILLING QTY" in text.upper():
        return "purchase"
    return "sale"


def process_pdfs(pdf_paths):
    sale_invoices, purchase_invoices = [], []
    for path in pdf_paths:
        fmt = detect_invoice_format(path)
        print(f"Processing ({fmt}): {path}")
        try:
            if fmt == "purchase":
                found = purchase_parse_invoices_from_pdf(path)
                purchase_invoices.extend(found)
            else:
                found = sale_parse_invoices_from_pdf(path)
                sale_invoices.extend(found)
        except Exception as e:
            print(f"Error processing {path}: {e}", file=sys.stderr)
    return sale_invoices, purchase_invoices


