def normalize_party_name(name):
    n = re.sub(r"[^A-Z0-9\s]", " ", (name or "").upper())
    return " ".join(n.split()).strip()


def party_match_score(a, b):
    na, nb = normalize_party_name(a), normalize_party_name(b)
    return SequenceMatcher(None, na, nb).ratio() if (na and nb) else 0.0


def product_key(row):
    cat, flav = row.get("PRODUCTS CATEGORY"), row.get("FLAVOUR")
    return f"{cat}|{flav}".upper() if (cat and flav) else None


PARTY_MATCH_THRESHOLD = 0.60
SALE_SIDE_COLUMNS = [
    "SALE INVOICE", "SALE DATE", "BOXES SOLD", "TOTAL PIECES SOLD",
    "SALE RATE W/O GST", "DISCOUNT ON SALE PRICE", "EFFECTIVE SALE RATE W/O GST",
    "SALE RATE WITH GST", "TOTAL SALE PRICE", "TOTAL SALE PRICE EXCLUSIVE OF GST",
]
COMBINED_REGISTER_COLUMNS = SALE_REGISTER_COLUMNS + [
    "SUPPLIER / PARTY (PURCHASE)", "GROSS PROFIT (EXCL. GST)", "GROSS PROFIT %",
]


def build_combined_register(purchase_rows, sale_rows):
    used_sale_idx = set()
    combined = []

    def merge(prow, srow):
        merged = dict(prow)
        merged.pop("_ship_to", None)
        merged["SUPPLIER / PARTY (PURCHASE)"] = prow.get("PARTY NAME", "")
        for col in SALE_SIDE_COLUMNS:
            merged[col] = srow.get(col, "")
        merged["PARTY NAME"] = srow.get("PARTY NAME", "")
        merged["GROSS PROFIT (EXCL. GST)"] = ""
        merged["GROSS PROFIT %"] = ""
        cost = merged.get("TOTAL COST PRICE EXCLUSIVE OF GST")
        sale_amt = merged.get("TOTAL SALE PRICE EXCLUSIVE OF GST")
        if isinstance(cost, (int, float)) and isinstance(sale_amt, (int, float)):
            profit = round(sale_amt - cost, 2)
            merged["GROSS PROFIT (EXCL. GST)"] = profit
            merged["GROSS PROFIT %"] = round(profit / cost * 100, 2) if cost else ""
        return merged

    for prow in purchase_rows:
        p_key = product_key(prow)
        p_invoice_no = clean(prow.get("PURCHASE INVOICE", ""))
        p_party = prow.get("_ship_to", "")

        exact_j = None
        if p_invoice_no:
            for j, srow in enumerate(sale_rows):
                if j in used_sale_idx:
                    continue
                if clean(srow.get("PURCHASE INVOICE", "")) != p_invoice_no:
                    continue
                s_key = product_key(srow)
                if p_key and s_key and p_key != s_key:
                    continue
                exact_j = j
                break

        if exact_j is not None:
            combined.append(merge(prow, sale_rows[exact_j]))
            used_sale_idx.add(exact_j)
            continue

        best_j, best_score = None, 0.0
        for j, srow in enumerate(sale_rows):
            if j in used_sale_idx:
                continue
            s_key = product_key(srow)
            if not p_key or not s_key or p_key != s_key:
                continue
            score = party_match_score(p_party, srow.get("PARTY NAME", ""))
            if score > best_score:
                best_score, best_j = score, j

        if best_j is not None and best_score >= PARTY_MATCH_THRESHOLD:
            combined.append(merge(prow, sale_rows[best_j]))
            used_sale_idx.add(best_j)
            continue

        merged = dict(prow)
        ship_to = merged.pop("_ship_to", "")
        merged["SUPPLIER / PARTY (PURCHASE)"] = prow.get("PARTY NAME", "")
        merged["PARTY NAME"] = ship_to
        merged["GROSS PROFIT (EXCL. GST)"] = ""
        merged["GROSS PROFIT %"] = ""
        combined.append(merged)

    for j, srow in enumerate(sale_rows):
        if j not in used_sale_idx:
            row = dict(srow)
            row["SUPPLIER / PARTY (PURCHASE)"] = ""
            row["GROSS PROFIT (EXCL. GST)"] = ""
            row["GROSS PROFIT %"] = ""
            combined.append(row)

    return combined


