        for i, v in enumerate(vals, start=1):
            c = ws2.cell(row=r2, column=i, value=v)
            c.font = NORMAL_FONT
            c.border = BORDER
            c.alignment = Alignment(vertical="top", wrap_text=True)
            if i in (8, 9, 10):
                c.number_format = "#,##0.00"
                c.alignment = Alignment(horizontal="right", vertical="top")
        r2 += 1
    for i, w in enumerate([26, 30, 18, 12, 20, 14, 22, 16, 15, 14], start=1):
        ws2.column_dimensions[get_column_letter(i)].width = w
    ws2.freeze_panes = "A4"

    ws3 = wb.create_sheet("Combined Register")
    ws3.sheet_view.showGridLines = False
    ws3["A1"] = "Combined Purchase + Sale Register"
    ws3["A1"].font = TITLE_FONT
    last_col3 = get_column_letter(len(COMBINED_REGISTER_COLUMNS))
    ws3.merge_cells(f"A1:{last_col3}1")
    style_header_row(ws3, 3, COMBINED_REGISTER_COLUMNS)

    numeric_cols = {
        "GRAMMAGE", "PIECES PER BOX", "BOX ORDERED", "TOTAL PIECES PURCHASED",
        "MRP/PIECE", "PUR RATE W/O GST", "DISCOUNT ON PUR RATE",
        "EFFECTIVE PUR RATE W/O GST", "BOXES SOLD", "TOTAL PIECES SOLD",
        "SALE RATE W/O GST", "DISCOUNT ON SALE PRICE", "EFFECTIVE SALE RATE W/O GST",
        "PURC RATE WITH GST", "SALE RATE WITH GST", "TOTAL COST PRICE",
        "TOTAL SALE PRICE", "TOTAL SALE PRICE EXCLUSIVE OF GST",
        "TOTAL COST PRICE EXCLUSIVE OF GST", "GROSS PROFIT (EXCL. GST)", "GROSS PROFIT %",
    }

    combined_rows = build_combined_register(
        build_purchase_register_rows(purchase_invoices),
        build_sale_register_rows(sale_invoices),
    )

    r3 = 4
    for crow in combined_rows:
        for i, col in enumerate(COMBINED_REGISTER_COLUMNS, start=1):
            c = ws3.cell(row=r3, column=i, value=crow.get(col, ""))
            c.font = NORMAL_FONT
            c.border = BORDER
            c.alignment = Alignment(vertical="top", wrap_text=True)
            if col in numeric_cols:
                c.alignment = Alignment(horizontal="right", vertical="top")
                c.number_format = "#,##0.00"
        r3 += 1

    for i, col in enumerate(COMBINED_REGISTER_COLUMNS, start=1):
        width = 30 if col in ("PARTY NAME", "PRODUCT NAME", "SUPPLIER / PARTY (PURCHASE)") else 16
        ws3.column_dimensions[get_column_letter(i)].width = width
    ws3.freeze_panes = "A4"

    wb.save(out_path)
